#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    int a[10];
    for(int i = 0; i < 10; i++) cin >> a[i];

    vector<vector<int>> adj(n+1), radj(n+1);
    vector<unordered_set<int>> adjset(n+1), radjset(n+1);

    for(int i = 0; i < m; i++){
        int u, v; cin >> u >> v;
        adj[u].push_back(v);
        radj[v].push_back(u);
        adjset[u].insert(v);
        radjset[v].insert(u);
    }

    auto now = chrono::steady_clock::now;
    auto start_time = now();
    auto elapsed_ms = [&](){ return chrono::duration_cast<chrono::milliseconds>(now() - start_time).count(); };

    // Check DAG — topological sort for longest path
    {
        vector<int> indeg(n+1, 0);
        for(int u = 1; u <= n; u++) for(int v : adj[u]) indeg[v]++;
        queue<int> q;
        for(int u = 1; u <= n; u++) if(indeg[u] == 0) q.push(u);
        vector<int> topo;
        topo.reserve(n);
        while(!q.empty()){
            int u = q.front(); q.pop(); topo.push_back(u);
            for(int v : adj[u]) if(--indeg[v] == 0) q.push(v);
        }
        if((int)topo.size() == n){
            vector<int> dp(n+1, 1), nxt(n+1, -1);
            for(int i = n-1; i >= 0; i--){
                int u = topo[i]; dp[u] = 1; nxt[u] = -1;
                for(int v : adj[u]) if(dp[v]+1 > dp[u]){ dp[u] = dp[v]+1; nxt[u] = v; }
            }
            int bs = topo[0];
            for(int u : topo) if(dp[u] > dp[bs]) bs = u;
            vector<int> path;
            for(int u = bs; u != -1; u = nxt[u]) path.push_back(u);
            cout << path.size() << "\n";
            for(int i = 0; i < (int)path.size(); i++){ if(i) cout << ' '; cout << path[i]; }
            cout << "\n";
            return 0;
        }
    }

    mt19937 rng(12345);
    vector<int> best_path;

    // Helper: count unvisited out-neighbors
    auto count_out = [&](int u, vector<bool>& inpath) -> int {
        int c = 0;
        for(int v : adj[u]) if(!inpath[v]) c++;
        return c;
    };
    auto count_in = [&](int u, vector<bool>& inpath) -> int {
        int c = 0;
        for(int v : radj[u]) if(!inpath[v]) c++;
        return c;
    };

    // Main loop: restarts
    while(elapsed_ms() < 3800 && (int)best_path.size() < n){
        int sv = rng() % n + 1;

        deque<int> path;
        path.push_back(sv);
        vector<bool> inpath(n+1, false);
        inpath[sv] = true;

        // Greedy extend back
        auto extend_back = [&]() -> bool {
            int c = path.back();
            int best = -1, bs = INT_MAX;
            for(int v : adj[c]){
                if(!inpath[v]){
                    int s = count_out(v, inpath);
                    if(s < bs || (s == bs && (rng()&1))){ bs = s; best = v; }
                }
            }
            if(best == -1) return false;
            path.push_back(best);
            inpath[best] = true;
            return true;
        };

        // Greedy extend front
        auto extend_front = [&]() -> bool {
            int c = path.front();
            int best = -1, bs = INT_MAX;
            for(int v : radj[c]){
                if(!inpath[v]){
                    int s = count_in(v, inpath);
                    if(s < bs || (s == bs && (rng()&1))){ bs = s; best = v; }
                }
            }
            if(best == -1) return false;
            path.push_front(best);
            inpath[best] = true;
            return true;
        };

        // Initial greedy build
        for(int rep = 0; rep < 3; rep++){
            while(extend_back());
            while(extend_front());
        }

        // Pósa rotation-extension
        // Convert deque to vector for rotation operations
        auto posa_improve = [&]() {
            // Convert to vector
            vector<int> vpath(path.begin(), path.end());
            int sz = (int)vpath.size();

            // Try rotating tail
            // tail = vpath[sz-1]. Look for vpath[sz-1] -> vpath[i] edge (i < sz-1).
            // Then new path = vpath[0..i] + reverse(vpath[i+1..sz-1])
            // New tail = vpath[i+1]
            // Then try to extend from new tail

            int max_rot_attempts = min(sz * 5, 2000);
            for(int attempt = 0; attempt < max_rot_attempts && elapsed_ms() < 3800; attempt++){
                int tail = vpath[sz-1];
                // Collect rotation candidates
                vector<int> cands;
                for(int i = 0; i < sz - 2; i++){
                    if(adjset[tail].count(vpath[i+1])){
                        // Can we form edge tail -> vpath[i+1]? No, we need tail -> vpath[i] wait...
                        // We need edge from vpath[sz-1] to some vpath[i] where i < sz-1
                        // Then reverse vpath[i+1..sz-1], new tail = old vpath[i+1]
                    }
                }
                // Actually: edge tail -> vpath[i] for some i in [1, sz-2]
                for(int i = 1; i < sz - 1; i++){
                    if(adjset[tail].count(vpath[i])){
                        cands.push_back(i);
                    }
                }
                if(cands.empty()) break;
                int idx = cands[rng() % cands.size()];
                // Reverse vpath[idx..sz-1] conceptually:
                // new path = vpath[0..idx-1] + tail + reversed(vpath[idx..sz-2])
                reverse(vpath.begin() + idx, vpath.end());
                // new tail
                int new_tail = vpath[sz-1];
                // Try extend
                bool extended = false;
                for(int v : adj[new_tail]){
                    if(!inpath[v]){
                        vpath.push_back(v);
                        inpath[v] = true;
                        sz++;
                        extended = true;
                        break;
                    }
                }
                if(!extended && attempt > max_rot_attempts/2) break;
            }
            path.assign(vpath.begin(), vpath.end());
        };

        posa_improve();

        // Try front rotations similarly
        {
            vector<int> vpath(path.begin(), path.end());
            int sz = (int)vpath.size();
            int max_rot = min(sz * 5, 2000);
            for(int attempt = 0; attempt < max_rot && elapsed_ms() < 3800; attempt++){
                int head = vpath[0];
                vector<int> cands;
                for(int i = 1; i < sz - 1; i++){
                    if(radjset[head].count(vpath[i])){
                        cands.push_back(i);
                    }
                }
                if(cands.empty()) break;
                int idx = cands[rng() % cands.size()];
                reverse(vpath.begin(), vpath.begin() + idx + 1);
                int new_head = vpath[0];
                bool extended = false;
                for(int v : radj[new_head]){
                    if(!inpath[v]){
                        vpath.insert(vpath.begin(), v);
                        inpath[v] = true;
                        sz++;
                        extended = true;
                        break;
                    }
                }
                if(!extended && attempt > max_rot/2) break;
            }
            path.assign(vpath.begin(), vpath.end());
        }

        if((int)path.size() > (int)best_path.size()){
            best_path.assign(path.begin(), path.end());
        }
        if((int)best_path.size() >= n) break;
    }

    cout << best_path.size() << "\n";
    for(int i = 0; i < (int)best_path.size(); i++){
        if(i) cout << ' ';
        cout << best_path[i];
    }
    cout << "\n";
}
